"""Torch-side matched study. Data fixtures are generated by prepare.py."""
import argparse, json, time, hashlib
from pathlib import Path
import numpy as np
import torch
from torch import nn

torch.set_num_threads(1)
HERE=Path(__file__).resolve().parent
SEEDS=(137,271,389)

def ap(y,p):
    order=np.argsort(-p, kind='mergesort'); yy=y[order]
    pos=np.flatnonzero(yy==1)
    return float(np.sum(np.cumsum(yy)[pos]/(pos+1))/yy.sum())

class Net(nn.Module):
    def __init__(self, init):
        super().__init__(); self.fill=nn.Parameter(torch.tensor(init,dtype=torch.float32)); self.register_buffer('fixed_fill',torch.tensor(init,dtype=torch.float32))
        self.net=nn.Sequential(nn.Linear(40,64),nn.BatchNorm1d(64),nn.ReLU(),nn.Dropout(.2),nn.Linear(64,32),nn.BatchNorm1d(32),nn.ReLU(),nn.Dropout(.2),nn.Linear(32,1))
    def forward(self,x,m,learn=True,mask_input=True):
        z=torch.where(m.bool(),self.fill[None,:] if learn else self.fixed_fill[None,:],x)
        return self.net(torch.cat([z,m if mask_input else torch.zeros_like(m)],1)).squeeze(1)

def run(mode, out):
    if mode not in ('validation','final'): raise ValueError(mode)
    rows=[]; timings={}
    for seed in SEEDS:
        d=np.load(HERE/f'fixture-{seed}.npz'); split='val' if mode=='validation' else 'test'
        xtr=d['xtr']; ytr=d['ytr']; med=d['median']; x=d[f'x{split}']; y=d[f'y{split}']; masks=d[f'masks_{split}']
        rng=np.random.default_rng(seed); aug_rng=np.random.default_rng(seed+700)
        start=time.perf_counter(); torch.manual_seed(seed)
        model=Net(med); opt=torch.optim.Adam(model.parameters(),lr=1e-3); best=-1; patience=0; best_state=None
        # per-example MCAR rate is sampled U(0,.4), as described.
        xt=torch.tensor(xtr); yt=torch.tensor(ytr,dtype=torch.float32)
        for epoch in range(80):
            model.train(); order=aug_rng.permutation(len(xt))
            for inds in np.array_split(order,max(1,int(np.ceil(len(order)/256)))):
                xb=xt[inds]; yb=yt[inds]
                rates=torch.rand((len(inds),1))*0.4; m=(torch.rand(xb.shape)<rates).float()
                # identical random masks for scalar and fixed-median matched arm
                opt.zero_grad(); logits=model(xb,m); loss=nn.functional.binary_cross_entropy_with_logits(logits,yb); loss.backward(); opt.step()
            model.eval()
            with torch.no_grad(): pred=torch.sigmoid(model(torch.tensor(x),torch.zeros_like(torch.tensor(x)))) .numpy()
            score=ap(y,pred)
            if score>best+1e-5: best=score; patience=0; best_state={k:v.detach().clone() for k,v in model.state_dict().items()}
            else: patience+=1
            if patience>=10: break
        model.load_state_dict(best_state); train_s=time.perf_counter()-start
        for arm in ('learned','fixed','no_mask','no_augmentation'):
            # Full separate matched fits except ablations are initialized independently.
            if arm=='learned': candidate=model
            else:
                torch.manual_seed(seed+{'fixed':100,'no_mask':200,'no_augmentation':300}[arm]); candidate=Net(med)
                opt=torch.optim.Adam(candidate.parameters(),lr=1e-3); aug_rng2=np.random.default_rng(seed+700)
                best=-1; patience=0; state=None
                for epoch in range(80):
                    candidate.train(); order=aug_rng2.permutation(len(xt))
                    for inds in np.array_split(order,max(1,int(np.ceil(len(order)/256)))):
                        xb=xt[inds]; yb=yt[inds]
                        if arm=='no_augmentation': m=torch.zeros_like(xb)
                        else:
                            rates=torch.rand((len(inds),1))*0.4; m=(torch.rand(xb.shape)<rates).float()
                        opt.zero_grad(); logits=candidate(xb,m,learn=False if arm=='fixed' else True,mask_input=arm!='no_mask'); loss=nn.functional.binary_cross_entropy_with_logits(logits,yb); loss.backward(); opt.step()
                    candidate.eval()
                    with torch.no_grad(): pred=torch.sigmoid(candidate(torch.tensor(x),torch.zeros_like(torch.tensor(x)),learn=False if arm=='fixed' else True,mask_input=arm!='no_mask')).numpy()
                    score=ap(y,pred)
                    if score>best+1e-5: best=score; patience=0; state={k:v.detach().clone() for k,v in candidate.state_dict().items()}
                    else: patience+=1
                    if patience>=10: break
                candidate.load_state_dict(state)
            candidate.eval()
            for j,level in enumerate((0,.1,.3,.5)):
                mm=masks[j]
                with torch.no_grad(): pred=torch.sigmoid(candidate(torch.tensor(x),torch.tensor(mm,dtype=torch.float32),learn=arm!='fixed',mask_input=arm!='no_mask')).numpy()
                rows.append({'seed':seed,'method':arm,'missing':level,'average_precision':ap(y,pred)})
        timings[str(seed)]={'train_seconds':train_s,'inference_seconds':None}
    result={'mode':mode,'seeds':SEEDS,'rows':rows,'timings':timings,'torch':torch.__version__}
    Path(out).write_text(json.dumps(result,indent=2)); return result

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('mode',choices=['validation','final']);p.add_argument('--output',required=True);a=p.parse_args();r=run(a.mode,a.output);print(json.dumps({'mode':a.mode,'rows':len(r['rows'])}))
